with exploded as (select id, plan, effective_from, currency, element from price_tiers lateral view outer explode(tier_limits) x as element), filtered as (select *, date_sub(effective_from, 77) as effective_from_minus_77d from exploded where effective_from >= to_date('2024-02-07') and element between 30 and 47), base as (select *, date_format(effective_from, 'yyyy-MM') as effective_from_label from filtered where effective_from >= to_date('2024-06-15') and element = 25), metrics as (select id, plan, currency, element, effective_from_minus_77d, effective_from_label, min(element) over (partition by plan) as plan_min_element, percent_rank() over (partition by plan order by element desc) as element_percent_rank, rank() over (partition by plan, currency order by element nulls last) as element_rank, rank() over (partition by plan order by element) as element_rank_2 from base where effective_from between '2024-02-09' and '2024-06-01'), filtered_price_tiers as (select effective_from_minus_77d, effective_from_label, plan_min_element, element_rank, element_rank_2, substring(plan, 1, 3) as plan_prefix from metrics where element_rank_2 <> 4), summary as (select case when element_rank >= 7 then 'LARGE' else 'SMALL' end as element_rank_tier, count(*) as row_count, approx_percentile(element_rank_2, 0.5) as element_rank_2_p50, percentile_approx(element_rank_2, 0.95) as element_rank_2_p95, max(plan_min_element) as max_plan_min_element, percentile_approx(element_rank_2, array(0.25, 0.5, 0.75)) as element_rank_2_quartiles, sum(element_rank) as total_element_rank from filtered_price_tiers group by case when element_rank >= 7 then 'LARGE' else 'SMALL' end) select element_rank_tier, row_count, element_rank_2_p50, element_rank_2_p95, max_plan_min_element, total_element_rank from summary;
